# Extract compressed blobs from the hex dump for the new entries
entries = [
    ("Invoice 2291 1", "4JwFwcERgDAIBMBWrgJnzM8SLAMJo3yOjJDUn92bK1wNrV0nPCFj/LGsQ9jxSeIxI9JYCKICohqT5XyPDW8RFPU="),
    ("Invoice 2291 2", "eJwFwcERgDAIBMBWrgJnzM8SLAMJo3yOjJDUn92bK1wNrV0nPCFj/LGsQ9jxSeIxI9JYCKICohqT5XyPDW8RFPU="),  # duplicate
    ("Parking", "eJwFwcENgDAMA8BVPAAGb8GMBk7pQFTU"),
]

import base64, zlib
for name, body_b64 in entries:
    try:
        decoded = base64.b64decode(body_b64)
        print(f"{name}: {len(decoded)} bytes, first 10 bytes: {decoded[:10].hex()}")
        # Try different decompression approaches
        if len(decoded) > 2 and decoded[:2] == b'\x78\x9c':
            try:
                decompressed = zlib.decompress(decoded[2:])
                text = decompressed.decode('utf-8')
                print(f"  Decompressed: {text}")
            except Exception as e:
                print(f"  Decompression (zlib) failed: {e}")
        else:
            try:
                decompressed = zlib.decompress(decoded)
                text = decompressed.decode('utf-8')
                print(f"  Decompressed: {text}")
            except Exception as e:
                print(f"  Decompression failed: {e}")
    except Exception as e:
        print(f"{name}: error - {e}")
    print()
EOF

